3	namespace App\Http\Controllers\Api\PublicSite;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\HashesClientData;
7	use App\Http\Controllers\Concerns\ResolvesSubdomainFromHost;
8	use App\Http\Requests\Api\PublicSite\PublicEnquiryRequest;
9	use App\Jobs\Notifications\SendEnquiryNotificationJob;
10	use App\Models\Analytics\LeadSubmission;
11	use App\Models\Core\Professional\Customer;
12	use App\Models\Core\Site\Block;
13	use App\Models\Core\Site\Enquiry;
14	use App\Services\Public\PublicSiteResolver;
15	use Illuminate\Http\JsonResponse;
16	use Illuminate\Http\Request;
17	
18	// V2: Handles public contact form submissions. Saves enquiry, upserts submitter as Customer lead, dispatches notification email.
19	class PublicEnquiryController extends ApiController
20	{
21	    use HashesClientData;
22	    use ResolvesSubdomainFromHost;
23	
24	    public function submit(PublicEnquiryRequest $request, PublicSiteResolver $resolver): JsonResponse
25	    {
26	        $data = $request->validated();
27	
28	        $subdomain = $this->resolveSiteSubdomain($request);
29	        $startedMs = $data['form_started_at_ms'] ?? null;
30	
31	        // 1) Honeypot: pretend success but record the abuse attempt.
32	        $honeypot = $data['website'] ?? null;
33	        if (is_string($honeypot) && trim($honeypot) !== '') {
34	            $this->logLead($request, $subdomain, null, null, 'honeypot', $startedMs);
35	
36	            return $this->success(['ok' => true]);
37	        }
38	
39	        // 2) Timing check: reject fires that are implausibly fast or old.
40	        if (is_int($startedMs)) {
41	            $nowMs = (int) floor(microtime(true) * 1000);
42	            $delta = $nowMs - $startedMs;
43	            $minMs = (int) config('sidest.form_timing.min_ms', 2500);
44	            $maxMs = (int) config('sidest.form_timing.max_ms', 12 * 60 * 60 * 1000);
45	
46	            if ($delta < $minMs || $delta > $maxMs) {
47	                $this->logLead($request, $subdomain, null, null, 'too_fast', $startedMs);
48	
49	                return $this->error('Invalid submission.', 422);
50	            }
51	        }
52	
53	        if (! $subdomain) {
54	            $this->logLead($request, null, null, null, 'no_subdomain', $startedMs);
55	
56	            return $this->error('Could not determine site from URL.', 400);
57	        }
58	
59	        $site = $resolver->resolvePublishedSite($subdomain);
60	        if (! $site || ! $site->professional_id) {
61	            $this->logLead($request, $subdomain, $site?->id, null, 'site_not_found', $startedMs);
62	
63	            return $this->error('Site not found.', 404);
64	        }
65	
66	        // 3) Contact block must be active on this site.
67	        $block = Block::query()
68	            ->where('site_id', $site->id)
69	            ->where('block_group', 'sections')
70	            ->where('block_type', 'contact')
71	            ->where('is_active', true)
72	            ->whereNull('deleted_at')
73	            ->first();
74	
75	        if (! $block) {
76	            return $this->error('This site is not accepting enquiries.', 422);
77	        }
78	
79	        // 4) Validate subject against merged options (platform defaults + affiliate additions).
80	        $defaults = (array) config('sidest.contact_subject_defaults', []);
81	        $custom = data_get($block->settings, 'subject_options');
82	        $custom = is_array($custom) ? $custom : [];
83	        $mergedOptions = array_values(array_unique(array_merge($defaults, $custom)));
84	
85	        if (! in_array($data['subject'], $mergedOptions, true)) {
86	            return $this->error('Invalid subject.', 422);
87	        }
88	
89	        // 5) Save the enquiry.
90	        $enquiry = Enquiry::query()->create([
91	            'professional_id' => $site->professional_id,
92	            'site_id' => $site->id,
93	            'name' => $data['name'],
94	            'email' => $data['email'],
95	            'phone' => $data['phone'] ?? null,
96	            'subject' => $data['subject'],
97	            'message' => $data['message'],
98	            'ip_hash' => $this->hashIp($request->ip()),
99	            'user_agent' => mb_substr((string) $request->userAgent(), 0, 500),
100	        ]);
101	
102	        // 6) Upsert submitter as Customer lead.
103	        $this->upsertEnquiryCustomer((string) $site->professional_id, $data['email'], $data['name'], $data['phone'] ?? null);
104	
105	        // 7) Log unified lead analytics.
106	        $this->logLead($request, $subdomain, $site->id, (string) $site->professional_id, 'created', $startedMs);
107	
108	        // 8) Dispatch notification email (only if settings.notification_email is present).
109	        $notificationEmail = data_get($block->settings, 'notification_email');
110	        if (is_string($notificationEmail) && trim($notificationEmail) !== '') {
111	            SendEnquiryNotificationJob::dispatch((string) $enquiry->id, trim($notificationEmail));
112	        }
113	
114	        return $this->success(['ok' => true]);
115	    }
116	
117	    private function upsertEnquiryCustomer(string $professionalId, string $email, ?string $fullName, ?string $phone): void
118	    {
119	        $normalizedEmail = strtolower(trim($email));
120	        if ($normalizedEmail === '') {
121	            return;
122	        }
123	
124	        $existing = Customer::query()
125	            ->withTrashed()
126	            ->where('professional_id', $professionalId)
127	            ->whereRaw('lower(email) = ?', [$normalizedEmail])
128	            ->first();
129	
130	        if ($existing) {
131	            if ($existing->trashed()) {
132	                $existing->restore();
133	            }
134	
135	            if ($fullName && trim((string) ($existing->full_name ?? '')) === '') {
136	                $existing->full_name = $fullName;
137	            }
138	
139	            if ($phone && trim((string) ($existing->phone ?? '')) === '') {
140	                $existing->phone = $phone;
141	            }
142	
143	            if (($existing->source ?? '') === '') {
144	                $existing->source = 'enquiry';
145	            }
146	
147	            $existing->save();
148	
149	            return;
150	        }
151	
152	        $customer = new Customer;
153	        $customer->professional_id = $professionalId;
154	        $customer->email = $normalizedEmail;
155	        $customer->full_name = $fullName ?: null;
156	        $customer->phone = $phone ?: null;
157	        $customer->source = 'enquiry';
158	        $customer->save();
159	    }
160	
161	    private function logLead(
162	        Request $request,
163	        ?string $subdomain,
164	        ?string $siteId,
165	        ?string $professionalId,
166	        string $outcome,
167	        ?int $formStartedAtMs,
168	    ): void {
169	        LeadSubmission::query()->create([
170	            'occurred_at' => now(),
171	            'subdomain' => $subdomain,
172	            'site_id' => $siteId,
173	            'professional_id' => $professionalId,
174	            'customer_id' => null,
175	            'ip_hash' => $this->hashIp($request->ip()),
176	            'user_agent' => $request->userAgent(),
177	            'referrer' => $request->headers->get('referer'),
178	            'outcome' => $outcome,
179	            'form_started_at_ms' => $formStartedAtMs,
180	        ]);
181	    }
182	}
