3	namespace App\Jobs\Notifications;
4	
5	use App\Mail\SiteEnquiryNotification;
6	use App\Models\Core\Site\Enquiry;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldQueue;
9	use Illuminate\Foundation\Bus\Dispatchable;
10	use Illuminate\Queue\InteractsWithQueue;
11	use Illuminate\Queue\SerializesModels;
12	use Illuminate\Support\Facades\Log;
13	use Illuminate\Support\Facades\Mail;
14	
15	// V2: Sends the contact-form notification email to the affiliate's configured inbox after an enquiry is saved.
16	class SendEnquiryNotificationJob implements ShouldQueue
17	{
18	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
19	
20	    public int $tries = 3;
21	
22	    public function __construct(
23	        public readonly string $enquiryId,
24	        public readonly string $notificationEmail,
25	    ) {
26	        $this->onQueue('notifications');
27	    }
28	
29	    public function handle(): void
30	    {
31	        $enquiry = Enquiry::query()->find($this->enquiryId);
32	
33	        if (! $enquiry) {
34	            Log::warning('SendEnquiryNotificationJob: enquiry not found', [
35	                'enquiry_id' => $this->enquiryId,
36	            ]);
37	
38	            return;
39	        }
40	
41	        Mail::to($this->notificationEmail)->send(new SiteEnquiryNotification($enquiry));
42	    }
43	}
