87	    /**
88	     * Configure the rate limiters for the application.
89	     */
90	    protected function configureRateLimiting(): void
91	    {
92	        $throttleEnabled = (bool) config('sidest.throttle.enabled', true);
93	
94	        // Health-check and ping endpoints
95	        RateLimiter::for('health-check', function (Request $request) use ($throttleEnabled) {
96	            if (! $throttleEnabled) {
97	                return Limit::none();
98	            }
99	
100	            return Limit::perMinute(60)->by($request->ip());
101	        });
102	
103	        // Public site endpoints (viewing sites, pages)
104	        RateLimiter::for('public-site', function (Request $request) use ($throttleEnabled) {
105	            if (! $throttleEnabled) {
106	                return Limit::none();
107	            }
108	
109	            return Limit::perMinute(60)
110	                ->by($request->ip())
111	                ->response(function () {
112	                    return response()->json([
113	                        'message' => 'Too many requests.  Please try again later.',
114	                    ], 429);
115	                });
116	        });
117	
118	        // Booking checkout — tighter limit because checkout hits Stripe/Square synchronously
119	        RateLimiter::for('booking-checkout', function (Request $request) use ($throttleEnabled) {
120	            if (! $throttleEnabled) {
121	                return Limit::none();
122	            }
123	
124	            return Limit::perMinute(10)
125	                ->by($request->ip())
126	                ->response(function () {
127	                    return response()->json([
128	                        'message' => 'Too many booking attempts. Please try again shortly.',
129	                    ], 429);
130	                });
131	        });
132	
133	        // Analytics endpoints (pageviews, clicks)
134	        RateLimiter::for('analytics', function (Request $request) use ($throttleEnabled) {
135	            if (! $throttleEnabled) {
136	                return Limit::none();
137	            }
138	
139	            return Limit::perMinute(120)
140	                ->by($request->ip());
141	        });
142	
143	        // Per-link click cap — secondary defense against sustained single-link spam
144	        RateLimiter::for('analytics-click', function (Request $request) use ($throttleEnabled) {
145	            if (! $throttleEnabled) {
146	                return Limit::none();
147	            }
148	
149	            $blockId = $request->input('block_id', 'unknown');
150	
151	            return Limit::perMinute(5)
152	                ->by($request->ip().':click:'.$blockId);
153	        });
154	
155	        // Customer lead submissions (form submissions)
156	        RateLimiter::for('leads', function (Request $request) use ($throttleEnabled) {
157	            if (! $throttleEnabled) {
158	                return [Limit::none()];
159	            }
160	
161	            $subdomain = $request->route('subdomain') ?? 'unknown';
162	
163	            return [
164	                // Per IP:  3 submissions per minute
165	                Limit::perMinute(3)
166	                    ->by($request->ip())
167	                    ->response(function () {
168	                        return response()->json([
169	                            'message' => 'Too many submissions. Please wait before trying again.',
170	                        ], 429);
171	                    }),
172	
173	                // Per subdomain: 100 submissions per minute (prevent abuse)
174	                Limit::perMinute(100)
175	                    ->by($subdomain)
176	                    ->response(function () {
177	                        return response()->json([
178	                            'message' => 'This site is receiving too many submissions. Please try again later.',
179	                        ], 429);
180	                    }),
181	            ];
182	        });
183	
184	        // Public waitlist submissions
185	        RateLimiter::for('waitlist', function (Request $request) use ($throttleEnabled) {
186	            if (! $throttleEnabled) {
187	                return [Limit::none()];
188	            }
189	
190	            $email = strtolower(trim((string) $request->input('email', '')));
191	            $emailKey = $email !== '' ? hash('sha256', $email) : 'unknown';
192	
193	            return [
194	                Limit::perMinute(5)
195	                    ->by('waitlist:ip:'.$request->ip())
196	                    ->response(function () {
197	                        return response()->json([
198	                            'message' => 'Too many waitlist submissions. Please try again shortly.',
199	                        ], 429);
200	                    }),
201	
202	                Limit::perHour(12)
203	                    ->by('waitlist:email:'.$emailKey)
204	                    ->response(function () {
205	                        return response()->json([
206	                            'message' => 'This email has been submitted recently. Please try again later.',
207	                        ], 429);
208	                    }),
209	            ];
210	        });
211	
212	        // Shopify webhook endpoints (keyed by shop domain, fallback to IP)
213	        RateLimiter::for('shopify-webhooks', function (Request $request) use ($throttleEnabled) {
214	            if (! $throttleEnabled) {
215	                return Limit::none();
216	            }
217	
218	            $key = strtolower(trim((string) $request->header('x-shopify-shop-domain', '')));
219	            if ($key === '') {
220	                $key = $request->ip();
221	            }
222	
223	            return Limit::perMinute(120)
224	                ->by($key)
225	                ->response(function () {
226	                    return response()->json(['message' => 'Too many webhook requests.'], 429);
227	                });
228	        });
229	
230	        // Affiliate selection write operations (create, delete, reorder)
231	        RateLimiter::for('affiliate-writes', function (Request $request) use ($throttleEnabled) {
232	            if (! $throttleEnabled) {
233	                return Limit::none();
